INSERT INTO `questions` (`id`, `text`, `content`, `active`, `order_index`) VALUES
(1, 'PENA DE MORTE: SIM OU NÃO?\n01 — SERÁ QUE FOI DEUS QUEM CRIOU A PENA DE MORTE? FAÇA O DOWNLOAD DA BÍBLIA ONLINE E CONHEÇA O AUTOR DA PENA DE MORTE: GÊNESIS 9:5, 6.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', 'PENA DE MORTE: SIM OU NÃO?\n01 — SERÁ QUE FOI DEUS QUEM CRIOU A PENA DE MORTE? FAÇA O DOWNLOAD DA BÍBLIA ONLINE E CONHEÇA O AUTOR DA PENA DE MORTE: GÊNESIS 9:5, 6.', 'color', '#0000FF')), 1, 1),
(2, '02 — O AUTOR DO APP, MISTER GANDHI, AFIRMA QUE A "LEI DA PENA DE MORTE" JÁ ESTÁ INSTAURADA NO BRASIL. SEGUNDO ELE, ELA É SANCIONADA PELA CONSTITUIÇÃO (ART. 228: OS MENORES DE 18 ANOS SÃO PENALMENTE INIMPUTÁVEIS), RATIFICADA PELO CONGRESSO ATRAVÉS DO ART. 27 DO CÓDIGO PENAL, PELO ART. 104 DO ECA (ESTATUTO DA CRIANÇA E DO ADOLESCENTE) E HOMOLOGADA PELO STF, SENDO CONSIDERADA APENAS UM "ATO INFRACIONAL". NA VERDADE, O QUE ESTES ARTIGOS DIZEM É QUE OS MENORES DE 18 ANOS PODEM FAZER TUDO, INCLUSIVE MATAR. VOCÊ ACHA QUE ELE ESTÁ CERTO?', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '02 — O AUTOR DO APP, MISTER GANDHI, AFIRMA QUE A "LEI DA PENA DE MORTE" JÁ ESTÁ INSTAURADA NO BRASIL. SEGUNDO ELE, ELA É SANCIONADA PELA CONSTITUIÇÃO (ART. 228: OS MENORES DE 18 ANOS SÃO PENALMENTE INIMPUTÁVEIS), RATIFICADA PELO CONGRESSO ATRAVÉS DO ART. 27 DO CÓDIGO PENAL, PELO ART. 104 DO ECA (ESTATUTO DA CRIANÇA E DO ADOLESCENTE) E HOMOLOGADA PELO STF, SENDO CONSIDERADA APENAS UM "ATO INFRACIONAL". NA VERDADE, O QUE ESTES ARTIGOS DIZEM É QUE OS MENORES DE 18 ANOS PODEM FAZER TUDO, INCLUSIVE MATAR. VOCÊ ACHA QUE ELE ESTÁ CERTO?', 'color', '#0000FF')), 1, 2),
(3, '03 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA FEMINICIDA (ASSASSINO DE MULHER: ESPOSA, NAMORADA, ETC.) E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA RESSARCIR OS FAMILIARES DA VÍTIMA? CERCA DE 10 MULHERES SÃO ASSASSINADAS TODOS OS DIAS NO BRASIL. A "LEI MARIA DA PENHA" SÓ DIMINUIU EM 10% O FEMINICÍDIO NO PAÍS.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '03 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA FEMINICIDA (ASSASSINO DE MULHER: ESPOSA, NAMORADA, ETC.) E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA RESSARCIR OS FAMILIARES DA VÍTIMA? CERCA DE 10 MULHERES SÃO ASSASSINADAS TODOS OS DIAS NO BRASIL. A "LEI MARIA DA PENHA" SÓ DIMINUIU EM 10% O FEMINICÍDIO NO PAÍS.', 'color', '#0000FF')), 1, 3),
(4, '04 — TALVEZ VOCÊ NÃO SEJA A FAVOR DA "PENA DE MORTE" PARA FEMINICIDAS, MAS VOCÊ CONCORDA COM A "LEI GANDHI ANTI-FEMINICÍDIO" NOS SEGUINTES MOLDES? UMA LEI DE PROTEÇÃO À VIDA E À INTEGRIDADE FÍSICA DA MULHER, BASEADA NA "LEI DA IGUALITARIEDADE DE DIREITOS" E NA "LEI DA JUSTA RECOMPENSA". SE ALGUÉM A AGREDIR, FERIR, MUTILAR, INCENDIAR OU CAUSAR-LHE MALES E DEFORMAÇÕES FÍSICAS, QUE SEJA FEITO O MESMO AO AGRESSOR, NA MESMA PROPORÇÃO. ALÉM DISSO, APLICAR-SE-IA A PENA DE PRISÃO PREVISTA EM LEI COM CUMPRIMENTO INTEGRAL, A ESPOLIAÇÃO DE SEUS BENS PARA INDENIZAR A VÍTIMA E, CASO SEJA NECESSÁRIO O TRANSPLANTE DE ALGUM ÓRGÃO (RINS, PULMÃO, ETC.), O AGRESSOR SERIA UM DOADOR COMPULSÓRIO. SE O ÓRGÃO NÃO FOR COMPATÍVEL COM A VÍTIMA, SERÁ DOADO AO SUS, COLOCANDO A VÍTIMA COMO O PRIMEIRO PACIENTE NA FILA DE ESPERA DE TRANSPLANTE. SIM OU NÃO? (NOTA: CERCA DE 21 MILHÕES DE MULHERES FORAM AGREDIDAS E ESPANCADAS EM 2017 NO BRASIL).', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '04 — TALVEZ VOCÊ NÃO SEJA A FAVOR DA "PENA DE MORTE" PARA FEMINICIDAS, MAS VOCÊ CONCORDA COM A "LEI GANDHI ANTI-FEMINICÍDIO" NOS SEGUINTES MOLDES? UMA LEI DE PROTEÇÃO À VIDA E À INTEGRIDADE FÍSICA DA MULHER, BASEADA NA "LEI DA IGUALITARIEDADE DE DIREITOS" E NA "LEI DA JUSTA RECOMPENSA". SE ALGUÉM A AGREDIR, FERIR, MUTILAR, INCENDIAR OU CAUSAR-LHE MALES E DEFORMAÇÕES FÍSICAS, QUE SEJA FEITO O MESMO AO AGRESSOR, NA MESMA PROPORÇÃO. ALÉM DISSO, APLICAR-SE-IA A PENA DE PRISÃO PREVISTA EM LEI COM CUMPRIMENTO INTEGRAL, A ESPOLIAÇÃO DE SEUS BENS PARA INDENIZAR A VÍTIMA E, CASO SEJA NECESSÁRIO O TRANSPLANTE DE ALGUM ÓRGÃO (RINS, PULMÃO, ETC.), O AGRESSOR SERIA UM DOADOR COMPULSÓRIO. SE O ÓRGÃO NÃO FOR COMPATÍVEL COM A VÍTIMA, SERÁ DOADO AO SUS, COLOCANDO A VÍTIMA COMO O PRIMEIRO PACIENTE NA FILA DE ESPERA DE TRANSPLANTE. SIM OU NÃO? (NOTA: CERCA DE 21 MILHÕES DE MULHERES FORAM AGREDIDAS E ESPANCADAS EM 2017 NO BRASIL).', 'color', '#0000FF')), 1, 4),
(5, '05 — EXISTE JUSTIÇA PARA ASSASSINOS NO BRASIL? SIM OU NÃO? JUSTIÇA É A IGUALDADE DE DIREITO ONDE A PENA É IGUAL AO DELITO; CASO HAJA DESIGUALDADE ENTRE AMBOS, HOUVE INJUSTIÇA. SE A PENA É MAIOR QUE O DELITO, SOMOS INJUSTOS COM O AGRESSOR; SE A PENA É MENOR QUE O DELITO, SOMOS INJUSTOS COM A VÍTIMA.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '05 — EXISTE JUSTIÇA PARA ASSASSINOS NO BRASIL? SIM OU NÃO? JUSTIÇA É A IGUALDADE DE DIREITO ONDE A PENA É IGUAL AO DELITO; CASO HAJA DESIGUALDADE ENTRE AMBOS, HOUVE INJUSTIÇA. SE A PENA É MAIOR QUE O DELITO, SOMOS INJUSTOS COM O AGRESSOR; SE A PENA É MENOR QUE O DELITO, SOMOS INJUSTOS COM A VÍTIMA.', 'color', '#0000FF')), 1, 5),
(6, '06 — UM BANDIDO MATA TODA UMA FAMÍLIA, GANHA 30 ANOS DE PRISÃO E SAI APÓS CUMPRIR 1/3 DELA (DEZ ANOS). HOUVE UMA JUSTIÇA PLENA E JUSTA? AQUELAS VIDAS SÓ VALEM DEZ ANOS DE PRISÃO DA VIDA DO ASSASSINO? O DIREITO DO ASSASSINO É MAIOR QUE O DA VÍTIMA? O ASSASSINO É CIDADÃO DE 1ª CLASSE E A VÍTIMA É CIDADÃO DE 2ª? UM É FILHO DE DEUS E O OUTRO É ENTEADO OU FILHO DO DIABO? O ART. 5º DA CONSTITUIÇÃO DIZ: "TODOS SÃO IGUAIS PERANTE A LEI, SEM DISTINÇÃO DE QUALQUER NATUREZA..."', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '06 — UM BANDIDO MATA TODA UMA FAMÍLIA, GANHA 30 ANOS DE PRISÃO E SAI APÓS CUMPRIR 1/3 DELA (DEZ ANOS). HOUVE UMA JUSTIÇA PLENA E JUSTA? AQUELAS VIDAS SÓ VALEM DEZ ANOS DE PRISÃO DA VIDA DO ASSASSINO? O DIREITO DO ASSASSINO É MAIOR QUE O DA VÍTIMA? O ASSASSINO É CIDADÃO DE 1ª CLASSE E A VÍTIMA É CIDADÃO DE 2ª? UM É FILHO DE DEUS E O OUTRO É ENTEADO OU FILHO DO DIABO? O ART. 5º DA CONSTITUIÇÃO DIZ: "TODOS SÃO IGUAIS PERANTE A LEI, SEM DISTINÇÃO DE QUALQUER NATUREZA..."', 'color', '#0000FF')), 1, 6),
(7, '07 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA ASSASSINOS MAIORES DE 18 ANOS E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA INDENIZAR A FAMÍLIA DA VÍTIMA? MAIS DE 40 MIL PESSOAS SÃO ASSASSINADAS TODOS OS ANOS NO BRASIL (EM 2017 FORAM CERCA DE 63.800) E, EM 1/3 DAS FAMÍLIAS BRASILEIRAS, HÁ UM ENTE QUERIDO QUE FOI ASSASSINADO.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '07 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA ASSASSINOS MAIORES DE 18 ANOS E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA INDENIZAR A FAMÍLIA DA VÍTIMA? MAIS DE 40 MIL PESSOAS SÃO ASSASSINADAS TODOS OS ANOS NO BRASIL (EM 2017 FORAM CERCA DE 63.800) E, EM 1/3 DAS FAMÍLIAS BRASILEIRAS, HÁ UM ENTE QUERIDO QUE FOI ASSASSINADO.', 'color', '#0000FF')), 1, 7),
(8, '08 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA RAPTORES (SEQUESTRADORES) DE PESSOAS PARA TRABALHO SEXUAL OU TRABALHO ESCRAVO E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA RESSARCIR OS FAMILIARES DA VÍTIMA? SEGUNDO A ONU, CERCA DE 2,5 MILHÕES DE PESSOAS POR ANO EM TODO O MUNDO SÃO VÍTIMAS DO TRÁFICO INTERNACIONAL — SENDO 2.400.000 MULHERES E METADE CRIANÇAS —, MOVIMENTANDO 150 BILHÕES DE DÓLARES ANUALMENTE.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '08 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA RAPTORES (SEQUESTRADORES) DE PESSOAS PARA TRABALHO SEXUAL OU TRABALHO ESCRAVO E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA RESSARCIR OS FAMILIARES DA VÍTIMA? SEGUNDO A ONU, CERCA DE 2,5 MILHÕES DE PESSOAS POR ANO EM TODO O MUNDO SÃO VÍTIMAS DO TRÁFICO INTERNACIONAL — SENDO 2.400.000 MULHERES E METADE CRIANÇAS —, MOVIMENTANDO 150 BILHÕES DE DÓLARES ANUALMENTE.', 'color', '#0000FF')), 1, 8),
(9, '09 — E SE A PESSOA RAPTADA FOSSE UM ENTE QUERIDO SEU (ESPOSA, ESPOSO, FILHO, FILHA, MÃE, PAI, IRMÃO, IRMÃ), VOCÊ SERIA A FAVOR DA “PENA DE MORTE” PARA O RAPTOR?', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '09 — E SE A PESSOA RAPTADA FOSSE UM ENTE QUERIDO SEU (ESPOSA, ESPOSO, FILHO, FILHA, MÃE, PAI, IRMÃO, IRMÃ), VOCÊ SERIA A FAVOR DA “PENA DE MORTE” PARA O RAPTOR?', 'color', '#0000FF')), 1, 9),
(10, '10 — VOCÊ É A FAVOR DA “PENA DE MORTE” PARA POLÍTICOS OU FUNCIONÁRIOS PÚBLICOS (CIVIS OU MILITARES) QUE DESVIAM DINHEIRO PÚBLICO (PECULATO)? ESSE É UM CRIME CONTRA O POVO E DEVE SER CONSIDERADO (GENOCÍDIO), E OS BENS DOS CULPADOS SERIAM ESPOLIADOS PARA RESSARCIR O ESTADO BRASILEIRO. MAIS DE 153.000 DOENTES MORREM TODOS OS ANOS NO SUS POR FALTA DE MÉDICOS, EM CONSEQUÊNCIA DOS MAIS DE 300 BILHÕES DE REAIS QUE SÃO DESVIADOS ANUALMENTE.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '10 — VOCÊ É A FAVOR DA “PENA DE MORTE” PARA POLÍTICOS OU FUNCIONÁRIOS PÚBLICOS (CIVIS OU MILITARES) QUE DESVIAM DINHEIRO PÚBLICO (PECULATO)? ESSE É UM CRIME CONTRA O POVO E DEVE SER CONSIDERADO (GENOCÍDIO), E OS BENS DOS CULPADOS SERIAM ESPOLIADOS PARA RESSARCIR O ESTADO BRASILEIRO. MAIS DE 153.000 DOENTES MORREM TODOS OS ANOS NO SUS POR FALTA DE MÉDICOS, EM CONSEQUÊNCIA DOS MAIS DE 300 BILHÕES DE REAIS QUE SÃO DESVIADOS ANUALMENTE.', 'color', '#0000FF')), 1, 10),
(11, '11 — VOCÊ ACHA QUE O BANDIDO QUE DÁ UM TIRO NA CABEÇA DE UMA PESSOA INDEFESA É MAIS IMPIEDOSO DO QUE O POLÍTICO QUE DESVIA 100 MILHÕES DOS COFRES PÚBLICOS? O BANDIDO MATA APENAS UM, ENQUANTO O POLÍTICO MATA MILHARES: CERCA DE 153 MIL MORTES POR ANO SÃO CAUSADAS POR MAU ATENDIMENTO, FALTA DE MÉDICOS OU FALTA DE MEDICAMENTOS NO SUS DEVIDO AO DESVIO DE VERBAS DO ESTADO.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '11 — VOCÊ ACHA QUE O BANDIDO QUE DÁ UM TIRO NA CABEÇA DE UMA PESSOA INDEFESA É MAIS IMPIEDOSO DO QUE O POLÍTICO QUE DESVIA 100 MILHÕES DOS COFRES PÚBLICOS? O BANDIDO MATA APENAS UM, ENQUANTO O POLÍTICO MATA MILHARES: CERCA DE 153 MIL MORTES POR ANO SÃO CAUSADAS POR MAU ATENDIMENTO, FALTA DE MÉDICOS OU FALTA DE MEDICAMENTOS NO SUS DEVIDO AO DESVIO DE VERBAS DO ESTADO.', 'color', '#0000FF')), 1, 11),
(12, '12 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-AUMENTO SALARIAL DOS POLÍTICOS"? ELA PROIBIRIA OS PARLAMENTARES DE VOTAREM EM PROJETOS DE LEI QUE VISEM AUMENTAR SEUS PRÓPRIOS SALÁRIOS. ISSO PASSARIA A SER FEITO POR COMISSÕES INDEPENDENTES E SANCIONADO PELO PRESIDENTE DA REPÚBLICA OU PELO STF, DE ACORDO COM O PERCENTUAL DA INFLAÇÃO, COMO OCORRE COM QUALQUER TRABALHADOR BRASILEIRO.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '12 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-AUMENTO SALARIAL DOS POLÍTICOS"? ELA PROIBIRIA OS PARLAMENTARES DE VOTAREM EM PROJETOS DE LEI QUE VISEM AUMENTAR SEUS PRÓPRIOS SALÁRIOS. ISSO PASSARIA A SER FEITO POR COMISSÕES INDEPENDENTES E SANCIONADO PELO PRESIDENTE DA REPÚBLICA OU PELO STF, DE ACORDO COM O PERCENTUAL DA INFLAÇÃO, COMO OCORRE COM QUALQUER TRABALHADOR BRASILEIRO.', 'color', '#0000FF')), 1, 12),
(13, '13 — VOCÊ É A FAVOR DA "LEI GANDHI DE PROTEÇÃO À VÍTIMA DE RAPTO"? ELA OBRIGARIA O RAPTOR, SOB PENA DE CHICOTADAS, A CONFESSAR ONDE ESCONDEU A VÍTIMA POUCAS HORAS ANTES DE SUA PRISÃO (APENAS EM CASOS DE RAPTO RECENTE E IMEDIATO, ONDE HAJA A POSSIBILIDADE DE A VÍTIMA AINDA ESTAR VIVA). O ARTIGO 5º, INCISO III DA CONSTITUIÇÃO, QUE DIZ: "NINGUÉM SERÁ SUBMETIDO A TORTURA NEM A TRATAMENTO DESUMANO OU DEGRADANTE", SÓ PROTEGE O BANDIDO?', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '13 — VOCÊ É A FAVOR DA "LEI GANDHI DE PROTEÇÃO À VÍTIMA DE RAPTO"? ELA OBRIGARIA O RAPTOR, SOB PENA DE CHICOTADAS, A CONFESSAR ONDE ESCONDEU A VÍTIMA POUCAS HORAS ANTES DE SUA PRISÃO (APENAS EM CASOS DE RAPTO RECENTE E IMEDIATO, ONDE HAJA A POSSIBILIDADE DE A VÍTIMA AINDA ESTAR VIVA). O ARTIGO 5º, INCISO III DA CONSTITUIÇÃO, QUE DIZ: "NINGUÉM SERÁ SUBMETIDO A TORTURA NEM A TRATAMENTO DESUMANO OU DEGRADANTE", SÓ PROTEGE O BANDIDO?', 'color', '#0000FF')), 1, 13),
(14, '14 — VOCÊ CONCORDA COM A "LEI GANDHI DE PROTEÇÃO À SAÚDE, À EDUCAÇÃO E À PESQUISA"? ELA PROPÕE QUE A VERBA DESTINADA A ESSAS ÁREAS SEJA SEMPRE AUMENTADA PERCENTUALMENTE NO MÍNIMO IGUAL OU ACIMA DA INFLAÇÃO, JAMAIS PODENDO SER DIMINUÍDA. ALÉM DISSO, PROPÕE UMA EMENDA CONSTITUCIONAL PARA TRANSFORMAR A REFERIDA LEI EM "CLÁUSULA PÉTREA" (OU SEJA, IMUTÁVEL). ATUALMENTE, QUANDO O GOVERNO PRECISA DE MAIS DINHEIRO, SEMPRE O RETIRA DA SAÚDE, DA EDUCAÇÃO E DA PESQUISA CIENTÍFICA.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '14 — VOCÊ CONCORDA COM A "LEI GANDHI DE PROTEÇÃO À SAÚDE, À EDUCAÇÃO E À PESQUISA"? ELA PROPÕE QUE A VERBA DESTINADA A ESSAS ÁREAS SEJA SEMPRE AUMENTADA PERCENTUALMENTE NO MÍNIMO IGUAL OU ACIMA DA INFLAÇÃO, JAMAIS PODENDO SER DIMINUÍDA. ALÉM DISSO, PROPÕE UMA EMENDA CONSTITUCIONAL PARA TRANSFORMAR A REFERIDA LEI EM "CLÁUSULA PÉTREA" (OU SEJA, IMUTÁVEL). ATUALMENTE, QUANDO O GOVERNO PRECISA DE MAIS DINHEIRO, SEMPRE O RETIRA DA SAÚDE, DA EDUCAÇÃO E DA PESQUISA CIENTÍFICA.', 'color', '#0000FF')), 1, 14),
(15, '15 — VOCÊ É A FAVOR DA “PENA DE MORTE” PARA ASSASSINOS MENORES DE 18 ANOS, MAS QUE TENHAM ACIMA DE 12 ANOS? A LEI DA INIMPUTABILIDADE PARA MENORES DE 18 ANOS É INCONSTITUCIONAL; NA VERDADE, O QUE A LEI ESTÁ DIZENDO É QUE O MENOR PODE MATAR. MESMO ASSIM, ELA PASSOU NO CONGRESSO E TEVE O AVAL DO STF, OS GUARDIÕES DA CONSTITUIÇÃO (ART. 102: "COMPETE AO SUPREMO TRIBUNAL FEDERAL, PRECIPUAMENTE, A GUARDA DA CONSTITUIÇÃO, CABENDO-LHE...").', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '15 — VOCÊ É A FAVOR DA “PENA DE MORTE” PARA ASSASSINOS MENORES DE 18 ANOS, MAS QUE TENHAM ACIMA DE 12 ANOS? A LEI DA INIMPUTABILIDADE PARA MENORES DE 18 ANOS É INCONSTITUCIONAL; NA VERDADE, O QUE A LEI ESTÁ DIZENDO É QUE O MENOR PODE MATAR. MESMO ASSIM, ELA PASSOU NO CONGRESSO E TEVE O AVAL DO STF, OS GUARDIÕES DA CONSTITUIÇÃO (ART. 102: "COMPETE AO SUPREMO TRIBUNAL FEDERAL, PRECIPUAMENTE, A GUARDA DA CONSTITUIÇÃO, CABENDO-LHE...").', 'color', '#0000FF')), 1, 15),
(16, '16 — VOCÊ É A FAVOR DA “PENA DE MORTE” PARA POLICIAL ASSASSINO DE PESSOA DESARMADA E INDEFESA, E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA RESSARCIR OS FAMILIARES DA VÍTIMA? HOUVE 6.413 ÓBITOS CAUSADOS PELA POLÍCIA EM 2024, E MUITOS DELES ERAM DE PESSOAS INOCENTES.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '16 — VOCÊ É A FAVOR DA “PENA DE MORTE” PARA POLICIAL ASSASSINO DE PESSOA DESARMADA E INDEFESA, E DE QUE OS SEUS BENS SEJAM ESPOLIADOS PARA RESSARCIR OS FAMILIARES DA VÍTIMA? HOUVE 6.413 ÓBITOS CAUSADOS PELA POLÍCIA EM 2024, E MUITOS DELES ERAM DE PESSOAS INOCENTES.', 'color', '#0000FF')), 1, 16),
(17, '17 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA POLICIAL CÚMPLICE E FALSA TESTEMUNHA EM FAVOR DE POLICIAL ASSASSINO DE PESSOA DESARMADA E INDEFESA, COM A ESPOLIAÇÃO DE SEUS BENS PARA RESSARCIR OS FAMILIARES DA VÍTIMA?', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '17 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA POLICIAL CÚMPLICE E FALSA TESTEMUNHA EM FAVOR DE POLICIAL ASSASSINO DE PESSOA DESARMADA E INDEFESA, COM A ESPOLIAÇÃO DE SEUS BENS PARA RESSARCIR OS FAMILIARES DA VÍTIMA?', 'color', '#0000FF')), 1, 17),
(18, '18 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA BANDIDOS QUE EXPLODEM CAIXAS ELETRÔNICOS (MULTIBANCO)? ISSO SERIA CLASSIFICADO COMO CRIME CONTRA O POVO (TERRORISMO, CRIME HEDIONDO). EM MUITAS CIDADES DO INTERIOR, IDOSOS PRECISAM VIAJAR DE 80 A 100 KM APENAS PARA SACAR DINHEIRO POR CAUSA DESSE CRIME.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '18 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA BANDIDOS QUE EXPLODEM CAIXAS ELETRÔNICOS (MULTIBANCO)? ISSO SERIA CLASSIFICADO COMO CRIME CONTRA O POVO (TERRORISMO, CRIME HEDIONDO). EM MUITAS CIDADES DO INTERIOR, IDOSOS PRECISAM VIAJAR DE 80 A 100 KM APENAS PARA SACAR DINHEIRO POR CAUSA DESSE CRIME.', 'color', '#0000FF')), 1, 18),
(19, '19 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA BANDIDOS QUE, EM ASSALTOS, EXPLODEM AS CAIXAS ELETRÔNICOS E USAM REFÉNS COMO ESCUDO HUMANO? ISSO DEMONSTRA TOTAL DESRESPEITO À VIDA ALHEIA, CONFIGURANDO UM CRIME CONTRA O POVO (TERRORISMO).', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '19 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA BANDIDOS QUE, EM ASSALTOS, EXPLODEM AS CAIXAS ELETRÔNICOS E USAM REFÉNS COMO ESCUDO HUMANO? ISSO DEMONSTRA TOTAL DESRESPEITO À VIDA ALHEIA, CONFIGURANDO UM CRIME CONTRA O POVO (TERRORISMO).', 'color', '#0000FF')), 1, 19),
(20, '20 — CASO NÃO SEJA A FAVOR DA "PENA DE MORTE", VOCÊ É A FAVOR DA "LEI GANDHI ANTI-HOMICÍDIO"? ELA PROPÕE QUE O CRIME DE HOMICÍDIO SEJA IMPRESCRITÍVEL, INAFIANÇÁVEL E COM CUMPRIMENTO INTEGRAL DA PENA NOS SEGUINTES MOLDES: SE ALGUÉM AGREDIR UMA PESSOA HUMANA — FERINDO-A, MUTILANDO-A, INCENDIANDO-A OU CAUSANDO-LHE MALES E DEFORMAÇÕES FÍSICAS —, QUE SEJA FEITO O MESMO AO AGRESSOR, NA MESMA PROPORÇÃO. SOMA-SE A ISSO A PENA DE PRISÃO PREVISTA EM LEI COM CUMPRIMENTO INTEGRAL, A ESPOLIAÇÃO DE SEUS BENS PARA INDENIZAÇÃO À VÍTIMA E, CASO SEJA NECESSÁRIO O TRANSPLANTE DE ALGUM ÓRGÃO (RINS, PULMÃO, ETC.), O AGRESSOR SERIA UM DOADOR COMPULSÓRIO. SE O ÓRGÃO NÃO FOR COMPATÍVEL, SERIA DOADO AO SUS, COLOCANDO A VÍTIMA COMO O PRIMEIRO PACIENTE NA FILA DE ESPERA. ATUALMENTE, O HOMICÍDIO PRESCREVE EM 20 ANOS (ART. 109 DO CÓDIGO PENAL), MAS O MORTO PERMANECE MORTO (A MORTE NÃO PRESCREVE). (NOTA: AJUSTEI O ARTIGO CITADO DE 21 PARA 109, QUE É O QUE REGE A PRESCRIÇÃO NO CÓDIGO PENAL BRASILEIRO).', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '20 — CASO NÃO SEJA A FAVOR DA "PENA DE MORTE", VOCÊ É A FAVOR DA "LEI GANDHI ANTI-HOMICÍDIO"? ELA PROPÕE QUE O CRIME DE HOMICÍDIO SEJA IMPRESCRITÍVEL, INAFIANÇÁVEL E COM CUMPRIMENTO INTEGRAL DA PENA NOS SEGUINTES MOLDES: SE ALGUÉM AGREDIR UMA PESSOA HUMANA — FERINDO-A, MUTILANDO-A, INCENDIANDO-A OU CAUSANDO-LHE MALES E DEFORMAÇÕES FÍSICAS —, QUE SEJA FEITO O MESMO AO AGRESSOR, NA MESMA PROPORÇÃO. SOMA-SE A ISSO A PENA DE PRISÃO PREVISTA EM LEI COM CUMPRIMENTO INTEGRAL, A ESPOLIAÇÃO DE SEUS BENS PARA INDENIZAÇÃO À VÍTIMA E, CASO SEJA NECESSÁRIO O TRANSPLANTE DE ALGUM ÓRGÃO (RINS, PULMÃO, ETC.), O AGRESSOR SERIA UM DOADOR COMPULSÓRIO. SE O ÓRGÃO NÃO FOR COMPATÍVEL, SERIA DOADO AO SUS, COLOCANDO A VÍTIMA COMO O PRIMEIRO PACIENTE NA FILA DE ESPERA. ATUALMENTE, O HOMICÍDIO PRESCREVE EM 20 ANOS (ART. 109 DO CÓDIGO PENAL), MAS O MORTO PERMANECE MORTO (A MORTE NÃO PRESCREVE). (NOTA: AJUSTEI O ARTIGO CITADO DE 21 PARA 109, QUE É O QUE REGE A PRESCRIÇÃO NO CÓDIGO PENAL BRASILEIRO).', 'color', '#0000FF')), 1, 20),
(21, '21 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA O FUNCIONÁRIO QUE DESVIA (E NÃO PULVERIZA) 1.000 LITROS DE SUBSTÂNCIA QUÍMICA DESTINADA A MATAR O MOSQUITO DA ZIKA, DENGUE E CHIKUNGUNYA NA CIDADE? ESTE SERIA UM CRIME CONTRA O POVO (GENOCÍDIO). ESTA PERGUNTA É UM TESTE PARA A SUA CONSCIÊNCIA, RESPONSABILIDADE E PARA VER SE VOCÊ É UMA PESSOA CONSEQUENTE.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '21 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA O FUNCIONÁRIO QUE DESVIA (E NÃO PULVERIZA) 1.000 LITROS DE SUBSTÂNCIA QUÍMICA DESTINADA A MATAR O MOSQUITO DA ZIKA, DENGUE E CHIKUNGUNYA NA CIDADE? ESTE SERIA UM CRIME CONTRA O POVO (GENOCÍDIO). ESTA PERGUNTA É UM TESTE PARA A SUA CONSCIÊNCIA, RESPONSABILIDADE E PARA VER SE VOCÊ É UMA PESSOA CONSEQUENTE.', 'color', '#0000FF')), 1, 21),
(22, '22 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA POLÍTICOS, FUNCIONÁRIOS PÚBLICOS OU POLICIAIS CORRUPTOS (ATIVOS OU PASSIVOS) QUE SUBORNAM OU DEIXAM-SE SUBORNAR? O CÂNCER DO BRASIL É A CORRUPÇÃO E PRECISAMOS EXTIRPÁ-LA. CERCA DE 300 BILHÕES DE REAIS POR ANO SÃO DESVIADOS ATRAVÉS DA CORRUPÇÃO.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '22 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA POLÍTICOS, FUNCIONÁRIOS PÚBLICOS OU POLICIAIS CORRUPTOS (ATIVOS OU PASSIVOS) QUE SUBORNAM OU DEIXAM-SE SUBORNAR? O CÂNCER DO BRASIL É A CORRUPÇÃO E PRECISAMOS EXTIRPÁ-LA. CERCA DE 300 BILHÕES DE REAIS POR ANO SÃO DESVIADOS ATRAVÉS DA CORRUPÇÃO.', 'color', '#0000FF')), 1, 22),
(23, '23 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA O GARIMPO ILEGAL QUE UTILIZA MERCÚRIO E SUBSTÂNCIAS TÓXICAS PROIBIDAS? TRATA-SE DE UM CRIME CONTRA O POVO (GENOCÍDIO). MUITOS INDÍGENAS JÁ NASCEM TETRAPLÉGICOS POR AÇÃO DO MERCÚRIO. EM MUITAS CIDADES DO AMAZONAS, OS PEIXES ESTÃO IMPRÓPRIOS PARA O CONSUMO POR CAUSA DISSO, E OS LENÇÓIS FREÁTICOS CONTAMINADOS AFETAM TODA A NAÇÃO.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '23 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA O GARIMPO ILEGAL QUE UTILIZA MERCÚRIO E SUBSTÂNCIAS TÓXICAS PROIBIDAS? TRATA-SE DE UM CRIME CONTRA O POVO (GENOCÍDIO). MUITOS INDÍGENAS JÁ NASCEM TETRAPLÉGICOS POR AÇÃO DO MERCÚRIO. EM MUITAS CIDADES DO AMAZONAS, OS PEIXES ESTÃO IMPRÓPRIOS PARA O CONSUMO POR CAUSA DISSO, E OS LENÇÓIS FREÁTICOS CONTAMINADOS AFETAM TODA A NAÇÃO.', 'color', '#0000FF')), 1, 23),
(24, '24 — CASO VOCÊ TENHA DISCORDADO DA "PENA DE MORTE EM CARÁTER EFETIVO" PARA ASSASSINOS E POLÍTICOS QUE DESVIAM DINHEIRO PÚBLICO, VOCÊ SERIA A FAVOR DA "LEI DA PENA DE MORTE EM CARÁTER EXPERIMENTAL"? ELA SERIA APLICADA POR APENAS 4 ANOS E, CASO DIMINUÍSSE SIGNIFICATIVAMENTE (60%) OS REFERIDOS CRIMES, A LEI TORNAR-SE-IA PERMANENTE.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '24 — CASO VOCÊ TENHA DISCORDADO DA "PENA DE MORTE EM CARÁTER EFETIVO" PARA ASSASSINOS E POLÍTICOS QUE DESVIAM DINHEIRO PÚBLICO, VOCÊ SERIA A FAVOR DA "LEI DA PENA DE MORTE EM CARÁTER EXPERIMENTAL"? ELA SERIA APLICADA POR APENAS 4 ANOS E, CASO DIMINUÍSSE SIGNIFICATIVAMENTE (60%) OS REFERIDOS CRIMES, A LEI TORNAR-SE-IA PERMANENTE.', 'color', '#0000FF')), 1, 24),
(25, '25 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA FALSIFICADORES E TRAFICANTES DE MEDICAMENTOS FALSIFICADOS? SEGUNDO A OMS, 10% DOS MEDICAMENTOS NO MUNDO SÃO FALSIFICADOS.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '25 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA FALSIFICADORES E TRAFICANTES DE MEDICAMENTOS FALSIFICADOS? SEGUNDO A OMS, 10% DOS MEDICAMENTOS NO MUNDO SÃO FALSIFICADOS.', 'color', '#0000FF')), 1, 25),
(26, '26 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA TRAFICANTES DE DROGAS PESADAS (COCAÍNA, CRACK, HEROÍNA, LSD, MORFINA, FENTANIL, XILAZINA, ETC.)?', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '26 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA TRAFICANTES DE DROGAS PESADAS (COCAÍNA, CRACK, HEROÍNA, LSD, MORFINA, FENTANIL, XILAZINA, ETC.)?', 'color', '#0000FF')), 1, 26),
(27, '27 — VOCÊ É A FAVOR DA "SUSPENSÃO IMEDIATA DA IMUNIDADE DIPLOMÁTICA OU IMUNIDADE PARLAMENTAR DOS POLÍTICOS" PARA FINS JURÍDICOS OU PENAIS QUANDO ELES FOREM SUSPEITOS DE CRIMES? O OBJETIVO SERIA FAZER COM QUE ELES SEJAM INVESTIGADOS E JULGADOS AINDA NO EXERCÍCIO DO MANDATO PARLAMENTAR. A IMUNIDADE DIPLOMÁTICA/PARLAMENTAR, NESSES CASOS, SÓ PROTEGE O BANDIDO E É INCONSTITUCIONAL, POIS FERE O ARTIGO 5º DA CONSTITUIÇÃO, QUE DIZ: "TODOS SÃO IGUAIS PERANTE A LEI".', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '27 — VOCÊ É A FAVOR DA "SUSPENSÃO IMEDIATA DA IMUNIDADE DIPLOMÁTICA OU IMUNIDADE PARLAMENTAR DOS POLÍTICOS" PARA FINS JURÍDICOS OU PENAIS QUANDO ELES FOREM SUSPEITOS DE CRIMES? O OBJETIVO SERIA FAZER COM QUE ELES SEJAM INVESTIGADOS E JULGADOS AINDA NO EXERCÍCIO DO MANDATO PARLAMENTAR. A IMUNIDADE DIPLOMÁTICA/PARLAMENTAR, NESSES CASOS, SÓ PROTEGE O BANDIDO E É INCONSTITUCIONAL, POIS FERE O ARTIGO 5º DA CONSTITUIÇÃO, QUE DIZ: "TODOS SÃO IGUAIS PERANTE A LEI".', 'color', '#0000FF')), 1, 27),
(28, '28 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA INCENDIÁRIOS FLORESTAIS CRIMINOSOS, DESMATAMENTO ILEGAL E TRÁFICO DE MADEIRA DE ÁRVORES EM VIAS DE EXTINÇÃO? MUNDIALMENTE, A FUMAÇA DE INCÊNDIOS PROVOCOU 154 MIL MORTES APENAS EM 2024, ALÉM DE MILHARES DE INTERNAÇÕES QUE GERAM PREJUÍZOS AOS COFRES PÚBLICOS.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '28 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA INCENDIÁRIOS FLORESTAIS CRIMINOSOS, DESMATAMENTO ILEGAL E TRÁFICO DE MADEIRA DE ÁRVORES EM VIAS DE EXTINÇÃO? MUNDIALMENTE, A FUMAÇA DE INCÊNDIOS PROVOCOU 154 MIL MORTES APENAS EM 2024, ALÉM DE MILHARES DE INTERNAÇÕES QUE GERAM PREJUÍZOS AOS COFRES PÚBLICOS.', 'color', '#0000FF')), 1, 28),
(29, '29 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-ATROPELAMENTO"? ELA OBRIGARIA O MOTORISTA QUE, DIRIGINDO EMBRIAGADO, ATROPELASSE ALGUÉM, A TER SEUS BENS ESPOLIADOS PARA INDENIZAR A VÍTIMA. O CRIME SERIA INAFIANÇÁVEL, SOMADO À PENA DE PRISÃO DESCRITA EM LEI COM CUMPRIMENTO INTEGRAL.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '29 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-ATROPELAMENTO"? ELA OBRIGARIA O MOTORISTA QUE, DIRIGINDO EMBRIAGADO, ATROPELASSE ALGUÉM, A TER SEUS BENS ESPOLIADOS PARA INDENIZAR A VÍTIMA. O CRIME SERIA INAFIANÇÁVEL, SOMADO À PENA DE PRISÃO DESCRITA EM LEI COM CUMPRIMENTO INTEGRAL.', 'color', '#0000FF')), 1, 29),
(30, '30 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-FUGA DE MENORES INFRATORES" DA INSTITUIÇÃO DE RESSOCIALIZAÇÃO ONDE CUMPREM A MEDIDA SOCIOEDUCATIVA? CASO HAJA FUGA, O MENOR ASSUMIRIA A MAIORIDADE PENAL, CUMPRINDO O RESTANTE DO TEMPO EM UMA PRISÃO VOLTADA PARA MENORES.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '30 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-FUGA DE MENORES INFRATORES" DA INSTITUIÇÃO DE RESSOCIALIZAÇÃO ONDE CUMPREM A MEDIDA SOCIOEDUCATIVA? CASO HAJA FUGA, O MENOR ASSUMIRIA A MAIORIDADE PENAL, CUMPRINDO O RESTANTE DO TEMPO EM UMA PRISÃO VOLTADA PARA MENORES.', 'color', '#0000FF')), 1, 30),
(31, '31 — VOCÊ É A FAVOR QUE O ESTADO BRASILEIRO FORNEÇA AO DEPENDENTE QUÍMICO A DROGA NECESSÁRIA PARA O SEU CONSUMO SEMANAL? POSTERIORMENTE, O ESTADO PODERIA SUBSTITUIR A DROGA PESADA POR OUTRA QUE CAUSE MENOS DEPENDÊNCIA E AJUDE NA CURA DO INDIVÍDUO. ESSA MEDIDA VISARIA DIMINUIR O NÚMERO DE ASSALTOS E MORTES CAUSADOS PELO VÍCIO.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '31 — VOCÊ É A FAVOR QUE O ESTADO BRASILEIRO FORNEÇA AO DEPENDENTE QUÍMICO A DROGA NECESSÁRIA PARA O SEU CONSUMO SEMANAL? POSTERIORMENTE, O ESTADO PODERIA SUBSTITUIR A DROGA PESADA POR OUTRA QUE CAUSE MENOS DEPENDÊNCIA E AJUDE NA CURA DO INDIVÍDUO. ESSA MEDIDA VISARIA DIMINUIR O NÚMERO DE ASSALTOS E MORTES CAUSADOS PELO VÍCIO.', 'color', '#0000FF')), 1, 31),
(32, '32 — VOCÊ É A FAVOR DA "PENA DE MORTE PARA HACKERS" QUE ENTRAM VIA INTERNET E DANIFICAM SITES PÚBLICOS COMO O DO MINISTÉRIO DA SAÚDE, DO SUS, DE HOSPITAIS, DE CASAS DE SAÚDE E DE MATERNIDADES, CAUSANDO MORTES E PREJUDICANDO A SAÚDE DE MILHARES DE VIDAS? ISSO SERIA CONSIDERADO UM CRIME CONTRA O POVO (GENOCÍDIO, TERRORISMO CIBERNÉTICO).', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '32 — VOCÊ É A FAVOR DA "PENA DE MORTE PARA HACKERS" QUE ENTRAM VIA INTERNET E DANIFICAM SITES PÚBLICOS COMO O DO MINISTÉRIO DA SAÚDE, DO SUS, DE HOSPITAIS, DE CASAS DE SAÚDE E DE MATERNIDADES, CAUSANDO MORTES E PREJUDICANDO A SAÚDE DE MILHARES DE VIDAS? ISSO SERIA CONSIDERADO UM CRIME CONTRA O POVO (GENOCÍDIO, TERRORISMO CIBERNÉTICO).', 'color', '#0000FF')), 1, 32),
(33, '33 — VOCÊ É A FAVOR DA "LEI GANDHI" PARA A CRIAÇÃO OFICIAL DA FFGF (FORÇA FEDERAL GUARDIÕES DA FLORESTA), COMPOSTA POR INDÍGENAS TREINADOS, ARMADOS MILITAR E TECNOLOGICAMENTE, E INCORPORADOS À POLÍCIA FEDERAL? QUEM ENTENDE E VIVE NA FLORESTA É O INDÍGENA, PODENDO PRESTAR UMA MELHOR VIGILÂNCIA.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '33 — VOCÊ É A FAVOR DA "LEI GANDHI" PARA A CRIAÇÃO OFICIAL DA FFGF (FORÇA FEDERAL GUARDIÕES DA FLORESTA), COMPOSTA POR INDÍGENAS TREINADOS, ARMADOS MILITAR E TECNOLOGICAMENTE, E INCORPORADOS À POLÍCIA FEDERAL? QUEM ENTENDE E VIVE NA FLORESTA É O INDÍGENA, PODENDO PRESTAR UMA MELHOR VIGILÂNCIA.', 'color', '#0000FF')), 1, 33),
(34, '34 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA BANDIDOS PORTANDO OU EXIBINDO ARMAS DE GUERRA (COMO METRALHADORA, FUZIL, GRANADA, DINAMITE E NITROGLICERINA) EM VIA PÚBLICA?', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '34 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA BANDIDOS PORTANDO OU EXIBINDO ARMAS DE GUERRA (COMO METRALHADORA, FUZIL, GRANADA, DINAMITE E NITROGLICERINA) EM VIA PÚBLICA?', 'color', '#0000FF')), 1, 34),
(35, '35 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-FUNCIONÁRIO FANTASMA"? ELA OBRIGARIA TODO PARLAMENTAR EM FIM DE MANDATO A ENTREGAR À AUTORIDADE RESPONSÁVEL A LISTA DE TODOS OS FUNCIONÁRIOS E ASSESSORES AO SEU SERVIÇO PARA AS DEVIDAS EXONERAÇÕES, EVITANDO SOBRECARREGAR O SETOR PÚBLICO. A DESOBEDIÊNCIA RESULTARIA EM UMA PENA DE 10 ANOS DE PRISÃO E MULTA DE 100 MIL REAIS PARA O POLÍTICO, ALÉM DE 15 ANOS DE PRISÃO PARA O FUNCIONÁRIO FANTASMA.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '35 — VOCÊ É A FAVOR DA "LEI GANDHI ANTI-FUNCIONÁRIO FANTASMA"? ELA OBRIGARIA TODO PARLAMENTAR EM FIM DE MANDATO A ENTREGAR À AUTORIDADE RESPONSÁVEL A LISTA DE TODOS OS FUNCIONÁRIOS E ASSESSORES AO SEU SERVIÇO PARA AS DEVIDAS EXONERAÇÕES, EVITANDO SOBRECARREGAR O SETOR PÚBLICO. A DESOBEDIÊNCIA RESULTARIA EM UMA PENA DE 10 ANOS DE PRISÃO E MULTA DE 100 MIL REAIS PARA O POLÍTICO, ALÉM DE 15 ANOS DE PRISÃO PARA O FUNCIONÁRIO FANTASMA.', 'color', '#0000FF')), 1, 35),
(36, '36 — VOCÊ É A FAVOR DA "LEI GANDHI DA DELAÇÃO PREMIADA" NOS SEGUINTES MOLDES: SE O ACUSADO NÃO COOPERAR COM A JUSTIÇA, A PENA AUMENTA EM 50%; SE COOPERAR, CUMPRE APENAS A PENA RECEBIDA? A ATUAL DELAÇÃO PREMIADA É UM VERDADEIRO PRÊMIO AOS CORRUPTOS.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '36 — VOCÊ É A FAVOR DA "LEI GANDHI DA DELAÇÃO PREMIADA" NOS SEGUINTES MOLDES: SE O ACUSADO NÃO COOPERAR COM A JUSTIÇA, A PENA AUMENTA EM 50%; SE COOPERAR, CUMPRE APENAS A PENA RECEBIDA? A ATUAL DELAÇÃO PREMIADA É UM VERDADEIRO PRÊMIO AOS CORRUPTOS.', 'color', '#0000FF')), 1, 36),
(37, '37 — VOCÊ É A FAVOR DA "LEI GANDHI PACIENTE FELIZ", QUE PUNE MÉDICOS QUE FALTAM AO PLANTÃO NO SUS PARA ATENDER EM CLÍNICAS PARTICULARES OU EM SEUS PRÓPRIOS CONSULTÓRIOS, MESMO SENDO PAGOS PELO ESTADO? A LEI TAMBÉM PUNIRIA COM 10 ANOS DE PRISÃO OS COLEGAS CÚMPLICES QUE ABONAM AS FALTAS DOS MESMOS (CORPORATIVISMO). A PENA SERIA DE 10 ANOS DE PRISÃO EFETIVA E MULTA DE 100 MIL REAIS.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '37 — VOCÊ É A FAVOR DA "LEI GANDHI PACIENTE FELIZ", QUE PUNE MÉDICOS QUE FALTAM AO PLANTÃO NO SUS PARA ATENDER EM CLÍNICAS PARTICULARES OU EM SEUS PRÓPRIOS CONSULTÓRIOS, MESMO SENDO PAGOS PELO ESTADO? A LEI TAMBÉM PUNIRIA COM 10 ANOS DE PRISÃO OS COLEGAS CÚMPLICES QUE ABONAM AS FALTAS DOS MESMOS (CORPORATIVISMO). A PENA SERIA DE 10 ANOS DE PRISÃO EFETIVA E MULTA DE 100 MIL REAIS.', 'color', '#0000FF')), 1, 37),
(38, '38 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA VIOLADORES (ESTUPRADORES) DE MULHERES (MAIORES OU MENORES) E DE VULNERÁVEIS? O BRASIL TEM CERCA DE 822 MIL CASOS DE ESTUPRO A CADA ANO — DOIS POR MINUTO.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '38 — VOCÊ É A FAVOR DA "PENA DE MORTE" PARA VIOLADORES (ESTUPRADORES) DE MULHERES (MAIORES OU MENORES) E DE VULNERÁVEIS? O BRASIL TEM CERCA DE 822 MIL CASOS DE ESTUPRO A CADA ANO — DOIS POR MINUTO.', 'color', '#0000FF')), 1, 38),
(39, '39 — VOCÊ ACHA QUE O BRASIL TEM UMA DEMOCRACIA PLENA, AMPLA E IRRESTRITA? NO PASSADO, O MILITAR APOSENTAVA-SE COM O SOLDO ACIMA DO RECEBIDO QUANDO ESTAVA NA ATIVA. QUANDO UM JUIZ COMETE UM CRIME, ELE É APENAS EXONERADO DO CARGO E APOSENTADO — OU MELHOR, PREMIADO, POIS VAI RECEBER SEM TRABALHAR. O MILITAR APOSENTADO, OUTRORA, AO MORRER DEIXAVA A APOSENTADORIA PARA A ESPOSA, E A ESPOSA DEIXAVA PARA OS FILHOS PERPETUAMENTE. E TODOS SOMOS IGUAIS PERANTE A CONSTITUIÇÃO (ART. 5º DA CONST. FEDERAL). MAS ALGUNS SÃO MAIS IGUAIS QUE OUTROS.', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '39 — VOCÊ ACHA QUE O BRASIL TEM UMA DEMOCRACIA PLENA, AMPLA E IRRESTRITA? NO PASSADO, O MILITAR APOSENTAVA-SE COM O SOLDO ACIMA DO RECEBIDO QUANDO ESTAVA NA ATIVA. QUANDO UM JUIZ COMETE UM CRIME, ELE É APENAS EXONERADO DO CARGO E APOSENTADO — OU MELHOR, PREMIADO, POIS VAI RECEBER SEM TRABALHAR. O MILITAR APOSENTADO, OUTRORA, AO MORRER DEIXAVA A APOSENTADORIA PARA A ESPOSA, E A ESPOSA DEIXAVA PARA OS FILHOS PERPETUAMENTE. E TODOS SOMOS IGUAIS PERANTE A CONSTITUIÇÃO (ART. 5º DA CONST. FEDERAL). MAS ALGUNS SÃO MAIS IGUAIS QUE OUTROS.', 'color', '#0000FF')), 1, 39),
(40, '40 — VOCÊ É A FAVOR DA PENA DE MORTE PARA FALSOS MÉDICOS QUE EXERCEM ILEGALMENTE A MEDICINA, SEM O DIPLOMA DE FACULDADE, SEM O NÚMERO DO CRM E SEM A APROVAÇÃO DO CONSELHO REGIONAL DE MEDICINA?', JSON_ARRAY(JSON_OBJECT('bold', true, 'text', '40 — VOCÊ É A FAVOR DA PENA DE MORTE PARA FALSOS MÉDICOS QUE EXERCEM ILEGALMENTE A MEDICINA, SEM O DIPLOMA DE FACULDADE, SEM O NÚMERO DO CRM E SEM A APROVAÇÃO DO CONSELHO REGIONAL DE MEDICINA?', 'color', '#0000FF')), 1, 40)
